func TestGettersBulkEmailValidateResponseEmailValidationResponsesItemDNS(t *testing.T) {
	t.Run("GetMxRecords", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &BulkEmailValidateResponseEmailValidationResponsesItemDNS{}
		var expected []string
		obj.MxRecords = expected

		// Act & Assert
		assert.Equal(t, expected, obj.GetMxRecords(), "getter should return the property value")
	})

	t.Run("GetMxRecords_NilValue", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &BulkEmailValidateResponseEmailValidationResponsesItemDNS{}
		obj.MxRecords = nil

		// Act & Assert
		assert.Nil(t, obj.GetMxRecords(), "getter should return nil when property is nil")
	})

	t.Run("GetMxRecords_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *BulkEmailValidateResponseEmailValidationResponsesItemDNS
		// Should not panic - getters should handle nil receiver gracefully
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("Getter panicked on nil receiver: %v", r)
			}
		}()
		_ = obj.GetMxRecords() // Should return zero value
	})

	t.Run("GetARecords", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &BulkEmailValidateResponseEmailValidationResponsesItemDNS{}
		var expected []string
		obj.ARecords = expected

		// Act & Assert
		assert.Equal(t, expected, obj.GetARecords(), "getter should return the property value")
	})

	t.Run("GetARecords_NilValue", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &BulkEmailValidateResponseEmailValidationResponsesItemDNS{}
		obj.ARecords = nil

		// Act & Assert
		assert.Nil(t, obj.GetARecords(), "getter should return nil when property is nil")
	})

	t.Run("GetARecords_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *BulkEmailValidateResponseEmailValidationResponsesItemDNS
		// Should not panic - getters should handle nil receiver gracefully
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("Getter panicked on nil receiver: %v", r)
			}
		}()
		_ = obj.GetARecords() // Should return zero value
	})

}

